"""2-D grid world with rooms, switches, resources and a hidden rule.

Design rules enforced here (MASTER SPEC 4.2):

* the subject only ever reads sensor-visible information; the hidden rule
  (``safe_color``) is exposed solely through :meth:`GridWorld.ground_truth`,
  which the cognitive loop never calls;
* map generation is seeded and replayable, and the generated parameters are part
  of the snapshot so an experiment can be reproduced exactly;
* train / validation / test map sets are generated by separate calls with
  separate seeds, and the rule is a property of the *set*, not of the layout, so
  learning a rule can transfer to unseen layouts.
"""

from __future__ import annotations

import json
import math
from collections import deque
from dataclasses import dataclass, field
from typing import Any

import numpy as np

from wphr.body.body import VirtualBody
from wphr.world.agents import ScriptedAgent, spawn_agents
from wphr.world.base import WorldObservation, WorldResult
from wphr.world.cells import (
    CELL_NAMES,
    COLOR_TO_CELL,
    INTERACTABLE,
    SOLID,
    SWITCH_COLORS,
    Cell,
)

ACTIONS: tuple[str, ...] = (
    "move_north",
    "move_east",
    "move_south",
    "move_west",
    "interact",
    "wait",
)


@dataclass
class GridMap:
    map_id: str
    width: int
    height: int
    rows: list[list[int]]
    start: tuple[int, int]
    safe_color: str
    params: dict[str, Any] = field(default_factory=dict)

    def copy(self) -> "GridMap":
        return GridMap(
            map_id=self.map_id,
            width=self.width,
            height=self.height,
            rows=[row[:] for row in self.rows],
            start=self.start,
            safe_color=self.safe_color,
            params=dict(self.params),
        )

    def snapshot(self) -> dict[str, Any]:
        return {
            "map_id": self.map_id,
            "width": self.width,
            "height": self.height,
            "rows": [row[:] for row in self.rows],
            "start": list(self.start),
            "safe_color": self.safe_color,
            "params": dict(self.params),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "GridMap":
        return cls(
            map_id=str(data["map_id"]),
            width=int(data["width"]),
            height=int(data["height"]),
            rows=[[int(v) for v in row] for row in data["rows"]],
            start=(int(data["start"][0]), int(data["start"][1])),
            safe_color=str(data.get("safe_color", "blue")),
            params=dict(data.get("params", {})),
        )


# --------------------------------------------------------------------- generation
def _components(rows: list[list[int]], width: int, height: int) -> list[list[tuple[int, int]]]:
    seen = [[False] * width for _ in range(height)]
    comps: list[list[tuple[int, int]]] = []
    for y in range(height):
        for x in range(width):
            if seen[y][x] or rows[y][x] in SOLID:
                continue
            queue = deque([(x, y)])
            seen[y][x] = True
            comp: list[tuple[int, int]] = []
            while queue:
                cx, cy = queue.popleft()
                comp.append((cx, cy))
                for dx, dy in ((0, -1), (1, 0), (0, 1), (-1, 0)):
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < width and 0 <= ny < height and not seen[ny][nx] and rows[ny][nx] not in SOLID:
                        seen[ny][nx] = True
                        queue.append((nx, ny))
            comps.append(comp)
    comps.sort(key=len, reverse=True)
    return comps


def generate_map(
    *,
    rng: np.random.Generator,
    width: int,
    height: int,
    wall_density: float,
    food: int,
    hazards: int,
    switches_blue: int,
    switches_orange: int,
    tools: int,
    safe_color: str,
    map_id: str,
) -> GridMap:
    """Generate a connected map; all placements are on the main component."""
    width = max(5, int(width))
    height = max(5, int(height))
    rows = [[int(Cell.FLOOR) for _ in range(width)] for _ in range(height)]
    for x in range(width):
        rows[0][x] = int(Cell.WALL)
        rows[height - 1][x] = int(Cell.WALL)
    for y in range(height):
        rows[y][0] = int(Cell.WALL)
        rows[y][width - 1] = int(Cell.WALL)

    start = (width // 2, height // 2)
    protected = {start, (start[0] + 1, start[1]), (start[0] - 1, start[1]),
                 (start[0], start[1] + 1), (start[0], start[1] - 1)}

    for y in range(1, height - 1):
        for x in range(1, width - 1):
            if (x, y) in protected:
                continue
            if float(rng.random()) < wall_density:
                rows[y][x] = int(Cell.WALL)

    comps = _components(rows, width, height)
    main = comps[0] if comps else [start]
    main_set = set(main)
    for comp in comps[1:]:
        cx, cy = comp[0]
        tx, ty = main[0]
        while cx != tx:
            cx += 1 if tx > cx else -1
            rows[cy][cx] = int(Cell.FLOOR)
        while cy != ty:
            cy += 1 if ty > cy else -1
            rows[cy][cx] = int(Cell.FLOOR)
        main_set.add(comp[0])
    # recompute the main component after carving
    comps = _components(rows, width, height)
    main = comps[0] if comps else [start]
    main_set = set(main)

    candidates = sorted(main_set - protected)
    rng.shuffle(candidates)
    need = food + hazards + switches_blue + switches_orange + tools
    if len(candidates) < need:
        raise ValueError(
            f"map too small for {need} objects: only {len(candidates)} free cells"
        )
    cursor = 0
    for _ in range(food):
        x, y = candidates[cursor]
        rows[y][x] = int(Cell.FOOD)
        cursor += 1
    for _ in range(hazards):
        x, y = candidates[cursor]
        rows[y][x] = int(Cell.HAZARD)
        cursor += 1
    for _ in range(switches_blue):
        x, y = candidates[cursor]
        rows[y][x] = int(Cell.SWITCH_BLUE)
        cursor += 1
    for _ in range(switches_orange):
        x, y = candidates[cursor]
        rows[y][x] = int(Cell.SWITCH_ORANGE)
        cursor += 1
    for _ in range(tools):
        x, y = candidates[cursor]
        rows[y][x] = int(Cell.TOOL)
        cursor += 1

    return GridMap(
        map_id=map_id,
        width=width,
        height=height,
        rows=rows,
        start=start,
        safe_color=safe_color,
        params={
            "width": width,
            "height": height,
            "wall_density": wall_density,
            "food": food,
            "hazards": hazards,
            "switches_blue": switches_blue,
            "switches_orange": switches_orange,
            "tools": tools,
        },
    )


def generate_map_set(
    *,
    count: int,
    seed: int,
    safe_color: str,
    prefix: str,
    width: int = 9,
    height: int = 9,
    wall_density: float = 0.18,
    food: int = 4,
    hazards: int = 3,
    switches_blue: int = 2,
    switches_orange: int = 2,
    tools: int = 1,
) -> list[GridMap]:
    """A set of layouts sharing one hidden rule; used for train/val/test splits."""
    maps: list[GridMap] = []
    for index in range(count):
        rng = np.random.default_rng(seed + 1000 * index)
        maps.append(
            generate_map(
                rng=rng,
                width=width,
                height=height,
                wall_density=wall_density,
                food=food,
                hazards=hazards,
                switches_blue=switches_blue,
                switches_orange=switches_orange,
                tools=tools,
                safe_color=safe_color,
                map_id=f"{prefix}_{index:03d}",
            )
        )
    return maps


# ------------------------------------------------------------------------- world
class GridWorld:
    world_id = "grid"

    def __init__(
        self,
        grid_map: GridMap,
        *,
        seed: int = 0,
        energy_start: float = 1.0,
        energy_cost_per_step: float = 0.0015,
        move_cost: float = 0.001,
        food_energy: float = 0.35,
        hazard_penalty: float = 0.30,
        tool_reward: float = 0.5,
        max_steps: int = 400,
        agents: int = 0,
        agent_cooperation: float = 0.7,
    ) -> None:
        self.map = grid_map
        self.width = grid_map.width
        self.height = grid_map.height
        self.seed = int(seed)
        self.energy_start = float(energy_start)
        self.energy_cost_per_step = float(energy_cost_per_step)
        self.move_cost = float(move_cost)
        self.food_energy = float(food_energy)
        self.hazard_penalty = float(hazard_penalty)
        self.tool_reward = float(tool_reward)
        self.max_steps = int(max_steps)
        self.agent_count = int(agents)
        self.agent_cooperation = float(agent_cooperation)
        self.agents: list[ScriptedAgent] = []
        self.rng = np.random.default_rng(self.seed)
        self.body = VirtualBody(
            x=grid_map.start[0], y=grid_map.start[1], heading="east", energy=self.energy_start
        )
        self.step = 0
        self.done = False
        self.episode_reward = 0.0
        self.events: list[dict[str, Any]] = []
        self.reset_objects()

    # ------------------------------------------------------------- lifecycle
    def reset_objects(self) -> None:
        self.step = 0
        self.done = False
        self.episode_reward = 0.0
        self.body = VirtualBody(
            x=self.map.start[0], y=self.map.start[1], heading="east", energy=self.energy_start
        )
        self.events = []
        self.agents = spawn_agents(
            self.agent_count, self.width, self.height, self.seed, self.agent_cooperation
        )

    def reset(self, seed: int | None = None) -> None:
        if seed is not None:
            self.seed = int(seed)
            self.rng = np.random.default_rng(self.seed)
        self.reset_objects()

    # ------------------------------------------------------------ observation
    def cell_at(self, x: int, y: int) -> int:
        if 0 <= x < self.width and 0 <= y < self.height:
            return int(self.map.rows[y][x])
        return int(Cell.WALL)

    def visible_cells(self, radius: int = 1) -> list[list[int]]:
        """Axis-aligned patch; out-of-bounds cells read as wall."""
        radius = max(0, int(radius))
        out: list[list[int]] = []
        for dy in range(-radius, radius + 1):
            row = []
            for dx in range(-radius, radius + 1):
                row.append(self.cell_at(self.body.x + dx, self.body.y + dy))
            out.append(row)
        return out

    def faced_position(self) -> tuple[int, int]:
        dx, dy = self.body.delta()
        return self.body.x + dx, self.body.y + dy

    def faced_cell(self) -> tuple[int, str]:
        x, y = self.faced_position()
        if self.agent_at(x, y) is not None:
            # agents are not rendered in the vision patch; they are sensed by the
            # social channel and named here so the cue vocabulary stays closed.
            return int(Cell.FLOOR), "agent"
        code = self.cell_at(x, y)
        name = CELL_NAMES[code] if 0 <= code < len(CELL_NAMES) else "wall"
        return code, name

    def agent_at(self, x: int, y: int) -> ScriptedAgent | None:
        for agent in self.agents:
            if agent.x == x and agent.y == y:
                return agent
        return None

    def visible_agent(self, radius: int = 3) -> dict[str, Any] | None:
        """Nearest agent within ``radius`` cells, as an observation (not ground truth)."""
        best: ScriptedAgent | None = None
        best_distance = float("inf")
        for agent in self.agents:
            distance = math.hypot(agent.x - self.body.x, agent.y - self.body.y)
            if distance <= radius and distance < best_distance:
                best, best_distance = agent, distance
        if best is None:
            return None
        dx = best.x - self.body.x
        dy = best.y - self.body.y
        return {
            "agent_id": best.agent_id,
            "distance": round(best_distance, 6),
            "bearing": math.atan2(dy, dx),
            "dx": int(dx),
            "dy": int(dy),
            "last_move": best.last_move,
        }

    def depth_ahead(self) -> int:
        dx, dy = self.body.delta()
        distance = 0
        x, y = self.body.x, self.body.y
        while distance < 32:
            x, y = x + dx, y + dy
            if self.cell_at(x, y) in SOLID:
                break
            distance += 1
        return distance

    def _nearest(self, target: int, limit: int = 8) -> tuple[int, int, float]:
        best = (0, 0, float("inf"))
        for y in range(self.height):
            for x in range(self.width):
                if self.cell_at(x, y) == target:
                    distance = math.hypot(x - self.body.x, y - self.body.y)
                    if distance < best[2]:
                        best = (x, y, distance)
        if best[2] > limit:
            return 0, 0, 0.0
        return best[0] - self.body.x, best[1] - self.body.y, best[2]

    def scent_profile(self) -> tuple[float, float, float]:
        dx, dy, distance = self._nearest(int(Cell.FOOD), limit=6)
        if distance == 0.0:
            return 0.0, 0.0, 0.0
        norm = max(1.0, math.hypot(dx, dy))
        return dx / norm, dy / norm, 1.0 / (1.0 + distance)

    def sound_profile(self) -> tuple[float, float, float]:
        dx, dy, distance = self._nearest(int(Cell.HAZARD), limit=5)
        if distance == 0.0:
            return 0.0, 0.0, 0.0
        return 1.0 / (1.0 + distance), math.atan2(dy, dx), distance / max(1.0, self.width)

    def contact_at_face(self) -> tuple[bool, float]:
        code, _name = self.faced_cell()
        solid = code in SOLID
        return solid, 1.0 if solid else 0.0

    def taste_profile(self) -> tuple[float, float]:
        code = self.cell_at(self.body.x, self.body.y)
        if code == int(Cell.FOOD):
            return 1.0, 0.0
        if code == int(Cell.HAZARD):
            return 0.0, 1.0
        return 0.0, 0.0

    def observe(self) -> WorldObservation:
        """Generic observation used alongside the detailed sensor suite."""
        code, name = self.faced_cell()
        values = [
            self.body.x / max(1, self.width),
            self.body.y / max(1, self.height),
            self.body.energy_ratio(),
            float(code) / max(1, len(CELL_NAMES) - 1),
            float(self.step) / max(1, self.max_steps),
        ]
        return WorldObservation(
            modality="multimodal",
            values=values,
            energy=self.body.energy_ratio(),
            step=self.step,
            source_device="simulator",
            confidence=1.0,
            meta={"map_id": self.map.map_id, "faced": name},
        )

    # ---------------------------------------------------------------- actions
    def actions(self) -> tuple[str, ...]:
        return ACTIONS

    def execute(self, action: str) -> WorldResult:
        if action not in ACTIONS:
            raise ValueError(f"invalid action for grid world: {action!r}")
        # The cue that the policy conditioned on is the cell faced *before* the
        # action. Credit assignment must use that cue, not whatever is faced
        # afterwards, otherwise a movement reward is credited to the wrong cue.
        pre_code, pre_cue = self.faced_cell()
        pre_x, pre_y = self.faced_position()
        self.step += 1
        self.body.spend(self.energy_cost_per_step)
        reward = -0.01
        reached = False
        cue_id = ""
        info: dict[str, Any] = {"action": action, "step": self.step}

        if action in ("move_north", "move_east", "move_south", "move_west"):
            heading = action.split("_", 1)[1]
            self.body.turn_to(heading)
            dx, dy = self.body.delta()
            nx, ny = self.body.x + dx, self.body.y + dy
            if self.cell_at(nx, ny) in SOLID:
                reward = -0.02
                info["blocked"] = True
            else:
                self.body.move_to(nx, ny)
                self.body.spend(self.move_cost)
                info["blocked"] = False
        elif action == "interact":
            if pre_cue == "agent":
                cue_id = f"agent_at_{pre_x}_{pre_y}"
                reward, reached = self._social_interaction(pre_x, pre_y, info)
            elif pre_code in INTERACTABLE:
                cue_id = f"obj_{pre_x}_{pre_y}"
                reward, reached = self._interact(pre_code, pre_x, pre_y, info)
            else:
                reward = -0.005
                info["interactable"] = False
        else:  # wait
            reward = -0.005

        for agent in self.agents:
            moved = agent.step(self)

        self.body.energy = float(max(0.0, min(1.0, self.body.energy)))
        self.episode_reward += reward
        if self.body.energy <= 0.0 or self.step >= self.max_steps:
            self.done = True
        info["cue"] = pre_cue
        info["cue_id"] = cue_id
        info["energy"] = round(self.body.energy, 6)
        self.events.append({"step": self.step, "action": action, "reward": reward})
        return WorldResult(
            action=action,
            success=not info.get("blocked", False),
            reward=float(reward),
            energy_after=float(self.body.energy),
            reached=reached,
            info=info,
        )

    def _social_interaction(self, x: int, y: int, info: dict[str, Any]) -> tuple[float, bool]:
        """Interact with another agent; cooperation is a hidden disposition."""
        agent = self.agent_at(x, y)
        if agent is None:
            info["interactable"] = False
            return -0.005, False
        cooperative = float(self.rng.random()) < agent.cooperation
        info.update(
            {
                "object": "agent",
                "interactable": True,
                "social": {
                    "agent_id": agent.agent_id,
                    "cooperative": bool(cooperative),
                },
            }
        )
        if cooperative:
            return 0.3, True
        return -0.05, False

    def _interact(self, code: int, x: int, y: int, info: dict[str, Any]) -> tuple[float, bool]:
        if code == int(Cell.FOOD):
            self.body.recharge(self.food_energy)
            self.map.rows[y][x] = int(Cell.FLOOR)
            info.update({"object": "food", "consumed": True, "interactable": True})
            return 1.0, True
        if code == int(Cell.HAZARD):
            self.body.take_hit(self.hazard_penalty)
            info.update({"object": "hazard", "harm": True, "interactable": True})
            return -1.0, False
        if code == int(Cell.TOOL):
            self.map.rows[y][x] = int(Cell.FLOOR)
            info.update({"object": "tool", "consumed": True, "interactable": True})
            return self.tool_reward, True
        if code in SWITCH_COLORS:
            color = SWITCH_COLORS[code]
            correct = color == self.map.safe_color
            if correct:
                self.map.rows[y][x] = int(Cell.FLOOR)
                self.body.recharge(0.1)
                info.update(
                    {"object": f"switch_{color}", "correct": True, "interactable": True}
                )
                return 1.0, True
            self.body.take_hit(self.hazard_penalty * 0.6)
            info.update(
                {"object": f"switch_{color}", "correct": False, "interactable": True}
            )
            return -1.0, False
        info["interactable"] = False
        return -0.005, False

    # ------------------------------------------------------------- hidden truth
    def ground_truth(self) -> dict[str, Any]:
        """Evaluation only: includes the hidden rule. Never called by the loop."""
        return {
            "safe_color": self.map.safe_color,
            "safe_cell": int(COLOR_TO_CELL[self.map.safe_color]),
            "map_id": self.map.map_id,
            "body": [self.body.x, self.body.y],
            "energy": self.body.energy,
            "step": self.step,
            "episode_reward": self.episode_reward,
        }

    # --------------------------------------------------------------- snapshot
    def snapshot(self) -> dict[str, Any]:
        return {
            "world_id": self.world_id,
            "map": self.map.snapshot(),
            "seed": self.seed,
            "body": self.body.snapshot(),
            "step": self.step,
            "done": self.done,
            "episode_reward": self.episode_reward,
            "agents": [agent.snapshot() for agent in self.agents],
            "rng_state": json.dumps(self.rng.bit_generator.state, sort_keys=True),
        }

    def restore(self, data: dict[str, Any]) -> None:
        self.map = GridMap.from_dict(data["map"])
        self.width = self.map.width
        self.height = self.map.height
        self.seed = int(data.get("seed", 0))
        self.body.restore(data.get("body", {}))
        self.step = int(data.get("step", 0))
        self.done = bool(data.get("done", False))
        self.episode_reward = float(data.get("episode_reward", 0.0))
        self.agents = [ScriptedAgent.from_dict(item) for item in data.get("agents", [])]
        self.agent_count = len(self.agents)
        self.rng = np.random.default_rng(self.seed)
        state = data.get("rng_state")
        if state:
            self.rng.bit_generator.state = json.loads(state)
